<?php elseif($view==='goals'): ?><section class="profile-panel"><div class="profile-panel-head"><div><h2>Minhas metas pessoais</h2><p>Defina objetivos acompanhados sobre vendas aprovadas sincronizadas.</p></div></div><form method="post" class="community-form personal-goal-form"><input type="hidden" name="csrf" value="<?= ap_e((string)$_SESSION['affiliate_portal_csrf']) ?>"><input type="hidden" name="action" value="personal_goal"><input type="hidden" name="view" value="goals"><label>Nome da meta<input name="title" maxlength="120" required></label><label>Métrica<select name="metric"><option value="revenue">Faturamento (R$)</option><option value="orders">Vendas</option><option value="new_customers">Novos clientes</option></select></label><label>Alvo<input name="target" type="number" min="0.01" step="0.01" required></label><label>Início<input name="start_date" type="date" required></label><label>Fim<input name="end_date" type="date" required></label><button type="submit">Criar meta</button></form><?php if($personalGoals): ?><div class="profile-goal-list"><?php foreach($personalGoals as $personalGoal): $goalTarget=(float)$personalGoal['target'];$goalPercent=$goalTarget>0?min(100,(float)$personalGoal['progress']/$goalTarget*100):0;$goalValue=$personalGoal['metric']==='revenue'?$fmt((int)round((float)$personalGoal['progress']*100)):number_format((float)$personalGoal['progress'],0,',','.');$goalTargetLabel=$personalGoal['metric']==='revenue'?$fmt((int)round($goalTarget*100)):number_format($goalTarget,0,',','.'); ?><article><span><?= ap_e(date('d/m/Y',strtotime($personalGoal['start_date']))) ?>–<?= ap_e(date('d/m/Y',strtotime($personalGoal['end_date']))) ?></span><h3><?= ap_e($personalGoal['title']) ?></h3><p><?= ap_e($goalValue) ?> / <?= ap_e($goalTargetLabel) ?> · <?= ap_e(['revenue'=>'faturamento','orders'=>'vendas','new_customers'=>'clientes novos'][$personalGoal['metric']]??$personalGoal['metric']) ?></p><div class="profile-progress"><span style="width:<?= ap_e(number_format($goalPercent,2,'.','')) ?>%"></span></div><small><?= ap_e(number_format($goalPercent,1,',','.')) ?>% concluído</small></article><?php endforeach; ?></div><?php else: ?><p class="profile-muted">Você ainda não criou metas pessoais.</p><?php endif; ?></section><section class="profile-panel"><div class="profile-panel-head"><div><h2>Metas e campanhas</h2><p>Campanhas ativas dos programas aos quais você está vinculado.</p></div></div><?php $goals=[];foreach($links as $link){$q=app_db()->prepare("SELECT id,title,metric,target,reward,start_date,end_date FROM campaigns WHERE tenant_id=? AND active=1 AND start_date<=CURRENT_DATE AND end_date>=CURRENT_DATE AND ((target_affiliate_id IS NULL AND (affiliate_group='all' OR affiliate_group=?)) OR target_affiliate_id=?) ORDER BY end_date");$q->execute([$link['tenant_id'],$link['affiliate_group'],$link['affiliate_id']]);foreach($q->fetchAll() as $g)$goals[]=[...$g,'producer_name'=>$link['producer_name'],'tenant_id'=>$link['tenant_id'],'affiliate_id'=>$link['affiliate_id']];}if(!$goals): ?><p class="profile-muted">Você não tem campanhas ativas vinculadas neste momento.</p><?php else: ?><div class="profile-goal-list"><?php foreach($goals as $goal): $progress=affiliate_portal_campaign_progress($goal);$target=(float)$goal['target'];$percent=$progress===null||$target<=0?null:min(100,$progress/$target*100);$metricLabel=['revenue'=>'faturamento','orders'=>'vendas','new_customers'=>'clientes novos','conversion'=>'conversão'][$goal['metric']]??'meta';$progressLabel=$progress===null?'Sem dados suficientes':($goal['metric']==='revenue'?$fmt((int)round($progress*100)):number_format($progress,$goal['metric']==='conversion'?2:0,',','.').($goal['metric']==='conversion'?'%':''));$targetLabel=$goal['metric']==='revenue'?$fmt((int)round($target*100)):number_format($target,$goal['metric']==='conversion'?2:0,',','.').($goal['metric']==='conversion'?'%':''); ?><article><span><?= ap_e($goal['producer_name']) ?> · <?= ap_e(date('d/m',strtotime($goal['start_date']))) ?>–<?= ap_e(date('d/m',strtotime($goal['end_date']))) ?></span><h3><?= ap_e($goal['title']) ?></h3><p><?= ap_e(ucfirst($metricLabel)) ?>: <?= ap_e($progressLabel) ?> / <?= ap_e($targetLabel) ?><?php if($goal['reward']!==''): ?> · Recompensa: <?= ap_e($goal['reward']) ?><?php endif; ?></p><?php if($percent!==null): ?><div class="profile-progress"><span style="width:<?= ap_e(number_format($percent,2,'.','')) ?>%"></span></div><small><?= ap_e(number_format($percent,1,',','.')) ?>% concluído</small><?php endif; ?></article><?php endforeach; ?></div><?php endif; ?></section>
