'description'])) ?></p><a href="<?= ap_e($material['resource_url']) ?>" target="_blank" rel="noopener noreferrer">Abrir material ↗</a></div></article><?php endforeach; ?></div><?php endif; ?></section>
<?php elseif($view==='events'): ?><section class="profile-panel"><div class="profile-panel-head"><div><h2>Reuniões e treinamentos</h2><p>Eventos dos produtores aos quais você está vinculado.</p></div></div><?php if(!$events): ?><p class="profile-muted">Nenhum evento programado para você.</p><?php else: ?><div class="profile-resource-list"><?php foreach($events as $event): ?><article><div><span class="profile-product-platform"><?= ap_e($event['producer_name']) ?> · <?= ap_e(date('d/m/Y H:i',strtotime($event['starts_at']))) ?></span><h3><?= ap_e($event['title']) ?></h3><p><?= nl2br(ap_e($event['description'])) ?></p><a href="<?= ap_e($event['meeting_url']) ?>" target="_blank" rel="noopener noreferrer">Abrir reunião ↗</a><p>Presença: <?= ap_e(['going'=>'Confirmada','declined'=>'Não participarei'][($event['response']??'')]??'Sem resposta') ?></p><?php if(($event['starts_at']??'')>date('Y-m-d H:i:s')): ?><form method="post" class="inline-response"><input type="hidden" name="csrf" value="<?= ap_e((string)$_SESSION['affiliate_portal_csrf']) ?>"><input type="hidden" name="action" value="event_response"><input type="hidden" name="view" value="events"><input type="hidden" name="event_id" value="<?= ap_e($event['id']) ?>"><button name="response" value="going" type="submit">Confirmar presença</button><button name="response" value="declined" type="submit">Não participarei</button></form><?php endif; ?></div></article><?php endforeach; ?></div><?php endif; ?></section>
<?php elseif($view==='messages'): ?><div class="support-layout"><section class="profile-panel"><div class="profile-panel-head"><div><h2>Meus atendimentos</h2><p>Conversas privadas com os produtores.</p></div></div><?php if(!$threads): ?><p class="profile-muted">Nenhum atendimento iniciado.</p><?php endif; ?><?php foreach($threads as $thread): ?><a class="support-thread-link <?= $thread['id']===$selectedThreadId?'selected':'' ?>" href="affiliate-dashboard.php?view=messages&amp;thread=<?= rawurlencode($thread['id']) ?>"><b><?= ap_e($thread['subject']) ?></b><span><?= ap_e($thread['producer_name']) ?> · <?= ap_e($thread['status']==='open'?'Aberta':'Encerrada') ?></span></a><?php endforeach; ?><form method="post" class="community-form message-new"><h3>Abrir solicitação</h3><input type="hidden" name="csrf" value="<?= ap_e((string)$_SESSION['affiliate_portal_csrf']) ?>"><input type="hidden" name="action" value="message_new"><input type="hidden" name="view" value="messages"><label>Programa<select name="tenant_id" required><option value="">Selecione um produtor</option><?php foreach($links as $link): ?><option value="<?= ap_e($link['tenant_id']) ?>"><?= ap_e($link['producer_name']) ?></option><?php endforeach; ?></select></label><label>Assunto<input name="subject" maxlength="160" required></label><label>Mensagem<textarea name="body" maxlength="5000" rows="3" required></textarea></label><button type="submit">Enviar ao produtor</button></form></section><section class="profile-panel"><?php if(!$selectedThread): ?><p class="profile-muted">Selecione um atendimento ou abra uma solicitação.</p><?php else: ?><div class="profile-panel-head"><div><h2><?= ap_e($selectedThread['subject']) ?></h2><p><?= ap_e($selectedThread['producer_name']) ?></p></div><span class="profile-status"><?= ap_e($selectedThread['status']) ?></span></div><div class="support-messages"><?php foreach($threadMessages as $message): ?><article class="<?= $message['sender_profile']==='affiliate'?'from-producer':'from-affiliate' ?>"><b><?= ap_e($message['sender_name']) ?></b><p><?= nl2br(ap_e($message['body'])) ?></p><small><?= ap_e(date('d/m/Y H:i',strtotime($message['created_at']))) ?></small></article><?php endforeach; ?></div><?php if($selectedThread['status']==='open'): ?><form method="post" class="community-form support-reply"><input type="hidden" name="csrf" value="<?= ap_e((string)$_SESSION['affiliate_portal_csrf']) ?>"><input type="hidden" name="action" value="message_reply"><input type="hidden" name="view" value="messages"><input type="hidden" name="thread_id" value="<?= ap_e($selectedThreadId) ?>"><label>Mensagem<textarea name="body" maxlength="5000" rows="4" required></textarea></label><button type="submit">Responder</button></form><?php endif; ?><?php endif; ?></section></div><?php endif; ?></main></body></html>
